uniform float amzp_c1active;
uniform float amzp_c1mode;
layout(color) uniform half4 amzp_c1color;
uniform float amzp_c1threshold;
uniform float amzp_c1feather;
uniform float amzp_c1luma;
uniform float amzp_c2active;
uniform float amzp_c2mode;
layout(color) uniform half4 amzp_c2color;
uniform float amzp_c2threshold;
uniform float amzp_c2feather;
uniform float amzp_c2luma;
uniform float amzp_c3active;
uniform float amzp_c3mode;
layout(color) uniform half4 amzp_c3color;
uniform float amzp_c3threshold;
uniform float amzp_c3feather;
uniform float amzp_c3luma;
uniform float amzp_c4active;
uniform float amzp_c4mode;
layout(color) uniform half4 amzp_c4color;
uniform float amzp_c4threshold;
uniform float amzp_c4feather;
uniform float amzp_c4luma;
uniform float amzp_showMask;


         float3x3 rgb2yuv = float3x3(
             0.299,     0.587,    0.114,
            -0.14713,  -0.28886,  0.436,
             0.615,    -0.51499, -0.10001
        );

         float3x3 yuv2rgb = float3x3(
            1.0,  0.0,      1.13983,
            1.0, -0.39465, -0.58060,
            1.0,  2.03211,  0.0
        );

        float4 calcKey(int mode, float4 keyColor, float threshold, float feather, float lumaSensitivity, float4 texColor, float3 texYUV ) {
            float3 keyYUV = keyColor.rgb * rgb2yuv;
            float dist = length((keyYUV - texYUV) * float3(lumaSensitivity,1.0,1.0));
            float a = 1. - smoothstep( threshold-max(feather,0.00001), threshold, dist );
            if( mode==0 ) {
                return float4(a,0.,1.,0.);
            } else if( mode==1 ) {
                return float4(0.,a,0.,1.);
            } else {
                return float4(0.);
            }
        }

        void amzRender() {


            float4 texColor = amzTexture(0,amzScreenNorm());

            float3 texYUV = texColor.rgb * rgb2yuv;

            float4 key = float4(0.);
            key += calcKey((amzp_c1active>0.5) ? int(amzp_c1mode) : 2, amzp_c1color, amzp_c1threshold, amzp_c1feather, amzp_c1luma, texColor, texYUV);
            key += calcKey((amzp_c2active>0.5) ? int(amzp_c2mode) : 2, amzp_c2color, amzp_c2threshold, amzp_c2feather, amzp_c2luma, texColor, texYUV);
            key += calcKey((amzp_c3active>0.5) ? int(amzp_c3mode) : 2, amzp_c3color, amzp_c3threshold, amzp_c3feather, amzp_c3luma, texColor, texYUV);
            key += calcKey((amzp_c4active>0.5) ? int(amzp_c4mode) : 2, amzp_c4color, amzp_c4threshold, amzp_c4feather, amzp_c4luma, texColor, texYUV);

            float alpha = clamp(step(0.5,key.z) - clamp(key.x,0.,1.) + clamp(key.y,0.,1.), 0., 1.);

            float2 halfFragSize = float2(1.0)/getTexSize((screen.zw/1.0))/2.;
            if(amzLayerNorm().x <= halfFragSize.x || amzLayerNorm().x >= 1.0 - halfFragSize.x || amzLayerNorm().y <= halfFragSize.y || amzLayerNorm().y >= 1.0 - halfFragSize.y) {
                alpha = 0.0;
            }






            amzOutput = (amzp_showMask>0.5) ? float4(alpha,0.,0.,1.)*texColor.a : float4(texColor.rgb*alpha,alpha*texColor.a);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

